`timescale 1ns/1ps
// Immutable pre-change modules are generated by run_led_storage.py.
module tb_led_storage_equivalence #(parameter int CE_PERIOD=4);
    import clk_rst_pkg::*;
    import pad_driver_pkg::*;
    logic clk=0,rst_n=0;
    always #5 clk=~clk;
    integer div=0;
    wire ce=div==CE_PERIOD-1;
    always @(posedge clk) if(!rst_n || ce)div<=0;else div<=div+1;
    clk_rst cr;
    assign cr={clk,ce,rst_n};
    mat4x4 force_map;
    logic [127:0] forces=0;
    assign force_map=forces;
    led_param a,b;
    wire da,db,ba,bb,fa,fb;
    pad_led_effects dut(cr,force_map,ba,fa,a);
    pad_led_effects_reference reference_fx(cr,force_map,bb,fb,b);
    led8x8 #(.ROTATE_180(0)) driver(cr,a.x,a.y,a.pix,a.wr,da,ba,fa);
    // Direct legacy read remains correct with consecutive enables as well.
    led8x8_reference #(.PIPELINED_READ(0)) reference_driver(cr,b.x,b.y,b.pix,b.wr,db,bb,fb);
    integer cycles=0,pixels=0,frames=0,resets=0;
    logic[31:0] random_state=32'h1fba8976;
    always @(negedge clk) if(rst_n)begin
        cycles++;
        if({da,ba,fa}!=={db,bb,fb})$fatal(1,"FAIL LED wire/control ce=%0d cycle=%0d",CE_PERIOD,cycles);
        if(a.wr!==b.wr || a.x!==b.x || a.y!==b.y)$fatal(1,"FAIL fill control");
        if(ce && a.wr)begin
            if(a.pix!==b.pix)$fatal(1,"FAIL pixel ce=%0d cycle=%0d xy=%0d,%0d",CE_PERIOD,cycles,a.x,a.y);
            pixels++;
        end
        if(fa)frames++;
    end
    task automatic clocks(input integer n);repeat(n)@(negedge clk);endtask
    task automatic reset_now;
        @(negedge clk);rst_n=0;forces=0;clocks(5);rst_n=1;resets++;
    endtask
    initial begin
        clocks(5);rst_n=1;
        // Reach wrap boundaries without waiting for millions of idle frames.
        @(negedge clk);
        force dut.travel_acc=24'hfff800;force reference_fx.travel_acc=24'hfff800;
        force dut.age_clock=16'hfffc;force reference_fx.age_clock=16'hfffc;
        @(negedge clk);
        release dut.travel_acc;release reference_fx.travel_acc;
        release dut.age_clock;release reference_fx.age_clock;
        forces='1;clocks(100);forces=0;
        repeat(60)begin
            clocks(137*CE_PERIOD);
            random_state=random_state^(random_state<<13);
            random_state=random_state^(random_state>>17);
            random_state=random_state^(random_state<<5);
            for(integer i=0;i<16;i++)forces[i*8 +:8]=random_state[i]?8'd220:8'd0;
        end
        wait(dut.state==dut.R_DISTANCE);reset_now(); // interrupt rendering
        forces='1;clocks(100);forces=0;
        wait(ba && driver.idx>200);reset_now(); // interrupt a serial frame
        forces='1;clocks(100);forces=0;
        wait(frames>=5);clocks(10);
        if(pixels<320 || resets!=2)$fatal(1,"FAIL insufficient coverage");
        $display("PASS tb_led_storage_equivalence CE_PERIOD=%0d cycles=%0d pixels=%0d frames=%0d warm_resets=%0d",CE_PERIOD,cycles,pixels,frames,resets);
        $finish;
    end
    initial begin #100000000;$fatal(1,"FAIL equivalence timeout");end
endmodule
